<template>
 <div class="app-container kit-process">
  <div class="heading"><div><h2>套装加工</h2><p>组装将组件转换为成品；拆卸将成品转换为组件。仓库受理不改变实存，实际加工结果确认后成组记账。</p></div><el-button v-hasPermi="['warehouse:process:edit']" type="primary" @click="newOrder">新建加工单</el-button></div>
  <el-form inline size="small" @submit.native.prevent="search"><el-form-item label="单号／SKU"><el-input v-model.trim="query.keyword" clearable placeholder="完整加工单号、套装SKU或仓库单号" @keyup.enter.native="search"/></el-form-item><el-form-item label="状态"><el-select v-model="query.state" clearable><el-option v-for="(label,key) in states" :key="key" :value="key" :label="label"/></el-select></el-form-item><el-button type="primary" @click="search">查询</el-button><el-button @click="load">刷新</el-button></el-form>
  <el-table :data="rows" v-loading="loading"><el-table-column label="加工单／类型" min-width="290"><template slot-scope="s"><el-button type="text" @click="open(s.row.id)">{{ s.row.process_sn }}</el-button><div>{{ operation(s.row.operation) }} · {{ s.row.create_time }}</div></template></el-table-column><el-table-column label="套装／虚拟仓" min-width="240"><template slot-scope="s">{{ s.row.goods_name }}<div class="muted">{{ s.row.sku_sn }} · {{ s.row.store_code }}</div></template></el-table-column><el-table-column label="加工进度（套）" width="185"><template slot-scope="s"><strong>{{ s.row.completed_quantity }} / {{ s.row.quantity }}</strong><div class="muted">剩余 {{ s.row.state==='STOPPED'?0:s.row.quantity-s.row.completed_quantity }}</div></template></el-table-column><el-table-column label="业务／仓库" width="190"><template slot-scope="s"><el-tag size="small">{{ states[s.row.state]||s.row.state }}</el-tag><div>{{ dispatches[s.row.dispatch_state]||s.row.dispatch_state }}</div></template></el-table-column><el-table-column label="待处理原因" min-width="210"><template slot-scope="s"><span class="warning">{{ s.row.last_error||'—' }}</span></template></el-table-column><el-table-column label="操作" width="90"><template slot-scope="s"><el-button type="text" @click="open(s.row.id)">详情</el-button></template></el-table-column></el-table>
  <pagination v-show="total>20" :total="total" :page.sync="query.page" :limit="20" @pagination="load"/>
  <el-dialog title="新建套装加工单" :visible.sync="creating" width="min(780px,96vw)" :close-on-click-modal="false" append-to-body><el-form label-width="110px" :model="form"><el-form-item label="作业类型"><el-radio-group v-model="form.operation" @change="batches=[];form.source_batch_id=null;loadBatches()"><el-radio label="ASSEMBLE">组装</el-radio><el-radio label="DISASSEMBLE">拆卸</el-radio></el-radio-group></el-form-item><el-form-item label="实物套装"><el-select v-model="form.sku_sn" filterable remote :remote-method="loadOptions" placeholder="搜索实物套装SKU／名称" @change="loadBatches"><el-option v-for="k in options.kits" :key="k.sku_sn" :value="k.sku_sn" :label="k.goods_name+' · '+k.sku_sn"/></el-select></el-form-item><el-form-item label="加工虚拟仓"><el-select v-model="form.store_code" filterable @change="loadBatches"><el-option v-for="w in options.stores" :key="w.store_code" :value="w.store_code" :disabled="!Number(w.storeprocess_enabled)" :label="w.store_name+' · '+w.store_code+' · '+w.owner_code+(Number(w.storeprocess_enabled)?'':'（未开通加工）')"/></el-select></el-form-item><el-form-item v-if="form.operation==='DISASSEMBLE'" label="原成品批次"><el-select v-model="form.source_batch_id" :loading="batchLoading" placeholder="选择本系统组装产出的批次"><el-option v-for="b in batches" :key="b.id" :value="b.id" :label="b.batch_code+' · 可用'+b.zp_available_number+'套 · '+b.process_sn"/></el-select><p class="muted">本期拆卸沿用原组装批次的组成和成本；外采成品拆卸待补充成本分摊依据后开放。</p></el-form-item><el-form-item label="计划套数"><el-input-number v-model="form.quantity" :min="1" :max="100000000" :precision="0"/></el-form-item><el-form-item label="操作依据"><el-input v-model.trim="form.reason" type="textarea" maxlength="255" placeholder="填写组装补货、拆卸原因等依据"/></el-form-item></el-form><el-alert :title="form.operation==='ASSEMBLE'?'投入下方组件，产出成品套装':'消耗原批次套装，按原组成回收组件'" type="info" :closable="false"/><el-table :data="preview"><el-table-column prop="sku_sn" label="组件SKU"/><el-table-column prop="quantity" label="每套件数"/><el-table-column label="本次计划件数"><template slot-scope="s">{{ s.row.quantity*form.quantity }}</template></el-table-column></el-table><div slot="footer"><el-button @click="creating=false">取消</el-button><el-button type="primary" :loading="acting" @click="create">保存草稿</el-button></div></el-dialog>
  <el-drawer title="套装加工详情" :visible.sync="visible" size="min(1180px,97vw)" append-to-body :wrapper-closable="false"><div class="detail" v-loading="detailLoading"><template v-if="detail"><div class="heading"><div><h3>{{ detail.process_sn }}</h3><p>{{ operation(detail.operation) }} · {{ detail.sku_sn }} · 组成版本 {{ detail.revision }}</p></div><el-tag>{{ states[detail.state]||detail.state }}</el-tag></div><div class="metrics"><div>计划 <strong>{{ detail.quantity }}</strong> 套</div><div>已完成并记账 <strong>{{ detail.completed_quantity }}</strong> 套</div><div>{{ detail.state==='STOPPED'?'已停止余量':'待完成' }} <strong>{{ detail.quantity-detail.completed_quantity }}</strong> 套</div></div><el-alert v-if="detail.last_error" :title="detail.last_error" type="warning" :closable="false" show-icon/><el-alert v-else :title="guidance" type="info" :closable="false" show-icon/><el-descriptions :column="2" border><el-descriptions-item label="加工虚拟仓">{{ detail.store_code }}</el-descriptions-item><el-descriptions-item label="实体仓／货主">{{ detail.real_store_code }} / {{ detail.owner_code }}</el-descriptions-item><el-descriptions-item label="仓库受理">{{ dispatches[detail.dispatch_state] }}</el-descriptions-item><el-descriptions-item label="仓库加工单号">{{ detail.external_order||'—' }}</el-descriptions-item><el-descriptions-item label="依据" :span="2">{{ detail.reason }}</el-descriptions-item></el-descriptions>
  <div class="actions"><el-button @click="open(detail.id)">刷新详情</el-button><el-button v-if="['DRAFT','RESERVING'].includes(detail.state)" v-hasPermi="['warehouse:process:edit']" type="primary" :loading="acting" @click="act('reserve')">{{ detail.state==='RESERVING'?'重试审核占用':'审核并占用投入库存' }}</el-button><el-button v-if="['READY','PARTIAL'].includes(detail.state)&&!['ACCEPTED','CANCELED'].includes(detail.dispatch_state)&&detail.last_action!=='CANCEL'" v-hasPermi="['warehouse:process:edit']" type="primary" :loading="acting" @click="act('dispatch')">{{ detail.dispatch_state==='PENDING'?'下发仓内加工单':'使用原加工单号重试受理' }}</el-button><el-button v-if="!['COMPLETED','STOPPED','RESERVING'].includes(detail.state)" v-hasPermi="['warehouse:process:edit']" :loading="acting" @click="stop">停止剩余加工</el-button><router-link :to="{path:'/oms-supplychain/wmsLogs',query:{number:detail.process_sn,numberType:'DOCUMENT',allTime:'true'}}">仓库交互日志</router-link><router-link :to="{path:'/oms-supplychain/wmsTickets',query:{noSn:detail.process_sn}}">加工出入库凭证</router-link></div>
  <h3>组成与投入占用</h3><el-table :data="detail.recipe.components"><el-table-column prop="sku_sn" label="组件SKU"/><el-table-column prop="goods_name" label="商品"/><el-table-column prop="quantity" label="每套件数"/></el-table><el-table v-if="detail.stock&&detail.stock.holds" :data="detail.stock.holds"><el-table-column prop="sku_sn" label="投入SKU"/><el-table-column prop="batch_code" label="占用批次"/><el-table-column prop="quantity" label="原占用"/><el-table-column prop="consumed_quantity" label="已消耗"/><el-table-column prop="released_quantity" label="已释放"/></el-table>
  <h3>加工回传与库存记账</h3><p class="muted">每次实际加工结果独立记录。待核对消息不会按计划自动增减库存；已记账消息重试不重复扣账。</p><article v-for="e in detail.events" :key="e.id" class="event"><div class="heading"><b>{{ e.message_id }} · 本次 {{ e.quantity }} 套</b><el-tag :type="e.state==='POSTED'?'success':'warning'">{{ e.state==='POSTED'?'投入与产出均已记账':'待核对／重试记账' }}</el-tag></div><p class="warning">{{ e.last_error }}</p><p v-if="e.reviewed" class="muted">差异确认：{{ e.review_actor }} · {{ e.review_reason }}</p><el-table :data="eventLines(e)"><el-table-column prop="side" label="库存方向" width="100"/><el-table-column prop="sku_sn" label="SKU"/><el-table-column prop="batch_code" label="批次"/><el-table-column prop="quantity" label="本次数量"/><el-table-column prop="inventory_type" label="良次品"/></el-table><div v-if="e.state!=='POSTED'" class="actions"><el-button v-hasPermi="['warehouse:process:edit']" :loading="acting" @click="act('event',{event_id:e.id})">按原消息重试记账</el-button><el-button v-if="!e.reviewed" v-hasPermi="['warehouse:process:edit']" :loading="acting" @click="review(e)">核实实际差异后确认</el-button></div></article><el-empty v-if="!detail.events.length" description="尚无仓库加工结果回传，实存尚未转换"/>
  <h3 v-if="detail.tickets.length">已生成库存凭证</h3><div v-for="t in detail.tickets" :key="t.id"><router-link :to="{path:'/oms-supplychain/wmsTickets',query:{sn:t.sn,documentId:t.id}}">{{ ticketLabels[t.business_type] }} · {{ t.sn }}</router-link></div>
  </template></div></el-drawer>
 </div>
</template>
<script>
import {processList,processOptions,processBatches,processDetail,processCreate,processAction} from '@/api/warehouse/process'
const key=()=>Date.now().toString(36)+'_'+Math.random().toString(36).slice(2)
export default {name:'KitProcess',data:()=>({query:{keyword:'',state:'',page:1},rows:[],total:0,loading:false,creating:false,visible:false,acting:false,detailLoading:false,batchLoading:false,detail:null,form:{},options:{kits:[],stores:[]},batches:[],states:{DRAFT:'草稿',RESERVING:'投入占用待确认',READY:'待加工',PARTIAL:'部分完成',COMPLETED:'加工完成',STOPPED:'剩余已停止'},dispatches:{PENDING:'未下发',SENDING:'下发中',ACCEPTED:'仓库已受理',FAILED:'下发失败',UNKNOWN:'交互结果待核对',CANCELED:'已停止'},ticketLabels:{ASSEMBLY_OUT:'组装耗料出库',ASSEMBLY_IN:'组装成品入库',DISASSEMBLY_OUT:'拆卸成品出库',DISASSEMBLY_IN:'拆卸组件入库'}}),computed:{preview(){const kit=this.options.kits.find(k=>k.sku_sn===this.form.sku_sn);return kit?this.object(kit.components):[]},guidance(){const d=this.detail;if(d.state==='DRAFT')return '审核时占用投入库存，尚不扣减实存；审核后再下发仓库。';if(d.state==='COMPLETED')return '本单加工结果已全部记账，关联凭证仅作查询，不重复通知仓库。';if(d.state==='STOPPED')return '剩余加工已停止，未消耗占用已释放，已完成的库存转换保留。';if(d.dispatch_state==='ACCEPTED')return '仓库已受理，等待实际加工结果；接单成功不代表成品已经入库。';return '投入库存已占用，请下发加工单；结果未知时沿用原单号重试，禁止换单重建。'}},watch:{'$route.query.id'(id){if(id)this.open(Number(id))}},created(){this.query.keyword=this.$route.query.sku||'';this.load();if(this.$route.query.id)this.open(Number(this.$route.query.id))},methods:{object(v){if(typeof v==='string')return JSON.parse(v);return v},operation(op){return op==='ASSEMBLE'?'组装':'拆卸'},async load(){this.loading=true;try{const r=await processList(this.query);this.rows=r.data.rows;this.total=r.data.total}finally{this.loading=false}},search(){this.query.page=1;this.load()},async loadOptions(keyword=''){this.options=(await processOptions({keyword})).data},async newOrder(){this.form={operation:'ASSEMBLE',sku_sn:this.$route.query.sku||'',store_code:'',quantity:1,source_batch_id:null,reason:'',request_key:key()};this.batches=[];await this.loadOptions(this.form.sku_sn);this.creating=true},async loadBatches(){this.form.source_batch_id=null;this.batches=[];if(this.form.operation!=='DISASSEMBLE'||!this.form.sku_sn||!this.form.store_code)return;this.batchLoading=true;try{this.batches=(await processBatches({sku:this.form.sku_sn,store:this.form.store_code})).data}finally{this.batchLoading=false}},async create(){if(!this.form.sku_sn||!this.form.store_code||!this.form.reason||this.form.operation==='DISASSEMBLE'&&!this.form.source_batch_id)return this.$message.warning('请补全套装、加工仓、计划数量、依据及拆卸来源');this.acting=true;try{const r=await processCreate(this.form);this.creating=false;await this.open(r.data.id);await this.load()}finally{this.acting=false}},async open(id){this.visible=true;this.detailLoading=true;try{this.detail=(await processDetail(id)).data}finally{this.detailLoading=false}},async act(action,extra={}){if(this.acting)return;this.acting=true;try{this.detail=(await processAction(this.detail.id,action,{control_version:this.detail.control_version,...extra})).data;await this.load()}finally{this.acting=false}},async stop(){const r=await this.$prompt('仓库已受理时，须由仓库明确确认停止后才释放剩余占用。请输入依据。','停止剩余加工',{inputValidator:v=>!!v&&v.trim().length>=2||'请填写停止依据'});await this.act('stop',{reason:r.value})},async review(e){const r=await this.$prompt('仅在核实原回传就是实际消耗和产出后确认，仍会校验原批次占用和剩余计划。请输入凭证或核对依据。','确认实际加工差异',{inputValidator:v=>!!v&&v.trim().length>=2||'请填写核对依据'});await this.act('review',{event_id:e.id,reason:r.value})},eventLines(e){const p=this.object(e.payload_json);return [...p.inputs.map(l=>({...l,side:'消耗出库'})),...p.outputs.map(l=>({...l,side:'产出入库'}))]}}}
</script>
<style scoped>.heading,.actions,.metrics{display:flex;align-items:center;justify-content:space-between;gap:14px;flex-wrap:wrap}.heading h2,.heading h3{margin:0 0 10px}.heading p,.muted{color:#7c899a;font-size:13px;line-height:1.8}.heading{margin-bottom:20px}.actions{justify-content:flex-start;margin:20px 0}.metrics{background:#f4f7fc;border:1px solid #e3eaf3;border-radius:8px;padding:20px;margin:16px 0}.metrics strong{font-size:25px;color:#30445f}.detail{padding:0 24px 30px}.detail .el-alert{margin:16px 0}.event{border:1px solid #e3eaf3;border-radius:8px;padding:18px;margin:16px 0}.warning{color:#af7414}.el-select{width:100%}.el-form--inline .el-select{width:180px}.el-form--inline .el-input{width:350px}.detail h3{margin-top:26px}</style>
